",{"dialogues":{"introProlog":[["Kirana","Tiga buku harus kukembalikan sebelum perpustakaan tutup. Rak cerita rakyat di bawah, pengetahuan di tengah, dan arsip di loteng."],["Kirana","Tangga besi di kanan menghubungkan ketiganya. Di meja arsip ada buku Keong Mas yang belum pernah kuselesaikan."]],"portal":[["Kirana","…dan Putri Candra Kirana dikutuk menjadi keong emas. Kenapa nggak ada satu pun anak sekarang yang tahu cerita ini, ya?"],["Kirana","…Lho. Tulisannya—"],["Narasi","Huruf-huruf terlepas dari halaman. Cahaya memenuhi loteng. Bunyi hujan berubah menjadi riuh sebuah pasar."]],"introPasar":[["Kirana","Ini bukan perpustakaan. Bau nasi hangat, sungai, atap-atap bambu… Aku ada di mana?"],["Mbok Rondo","Nduk, kowe katon luwe. Mampir warung mbok dhisik."]],"mbok":[["Kirana","Terima kasih, Mbok… tapi saya tidak punya uang. Dan sejujurnya saya juga tidak tahu saya ada di mana."],["Mbok Rondo","Mbok ngerti. Bantu mbok telu wae. Antar pesanan ke pembuat gerabah, pengangkut padi, dan penjaga atap. Mengko mbok wenehi sing luwih penting tinimbang sega."]],"chase":[["Penjaga atap","Terima kasih! Eh—lutung itu membawa bungkusan Mbok!"],["Kirana","Tunggu! Aku cuma ingin tahu apa yang kamu bawa."],["Narasi","Lutung melompat dari atap ke atap menuju dermaga. Ikuti jalur atas; pasar di belakang mulai lenyap dari pandangan."]],"asih":[["Kirana","Kamu lapar juga, ya? Ini sisa sarapanku."],["Narasi","Lutung mengambil makanan itu dan meletakkan bungkusan di tangan Kirana."],["Mbok Rondo","Gawanen menyang Tuan Putri Candra Kirana ing Kedaton Dhaha. Sing isih éling, mung kowe."]],"introPetirtaan":[["Kirana","Serat Asih berpendar ketika aku memasuki taman. Tetapi batu-batunya seperti sedang kehilangan bentuk."],["Kirana","Ada seorang abdi di dekat damar. Mungkin ia tahu jalan menuju kedaton."]],"jati":[["Ki Jati","Pakaianmu asing, Nak. Tapi tanganmu memegang sesuatu yang kukenal lebih baik daripada wajahku sendiri."],["Kirana","Saya Kirana. Mbok penjual di pasar meminta saya menyerahkan ini pada Tuan Putri."],["Ki Jati","Pecahan Serat. Tiga tahun terakhir, tembok ini mulai kosong sendiri. Dulu di sini ada gambar Putri memberi makan burung. Aku tidak lagi ingat bentuknya."],["Kirana","Ki… kenapa Ki Jati menangis?"],["Ki Jati","Kemarin aku memanggil anakku. Lalu aku sadar aku tidak tahu nama yang kupanggil."],["Ki Jati","Bawalah Pelita Ingatan. Selama ia menyala, yang terlupa masih bisa dipijak. Buka Hulu dan Akar, tutup Hilir. Tunggu di damar tengah."]],"sabar":[["Kirana","Satu demi satu relief menyala ketika kolam penuh. Air itu menyelesaikan ceritanya sendiri."],["Ki Jati","Kini balik alirannya: tutup Hulu dan Akar, buka Hilir. Pelitamu sudah bisa menahan pijakan yang memudar. Di depan relief, diam dan tahan cahayanya; kubantu membaca huruf pertamanya."]],"jujur":[["Kirana","Aku hampir mengisi bagian kosong dengan tebakanku. Tetapi urutan peristiwanya masih ada di dinding ini."],["Ki Jati","Kau telah membaca yang tertulis. Bawalah Serat Jujur. Jalan berikutnya menanjak ke tempat sunyi."]],"introBukit":[["Kirana","Obor emas yang berdiri di atas batu adalah Damar Pengingat. Mendekatinya menyimpan perjalanan dan mengisi minyak. Damar Jurang ada di teras sebelum jembatan putus; penunjuk akan menuntunku ke sana."],["Kirana","Dari Damar Jurang, aku harus ke tepi kanan, menahan X, lalu melompat dengan Z melalui pijakan bercahaya. Di dekat gulungan Wani, tetap tahan X dan tekan C. Setelah itu barulah naik ke Kilisuci."]],"kilisuci":[["Dewi Kilisuci","Aku Kilisuci. Yang memilih menyepi agar tak menjadi rebutan."],["Kirana","Kutukan apa sebenarnya yang menimpa Tuan Putri?"],["Dewi Kilisuci","Bukan sihir hitam, Nak. Kutukannya bernama kelalaian. Di zamanmu kisah beliau tak lagi diceritakan. Tanpa diingat, ia tak ada."],["Kirana","Jadi yang membuat Putri menghilang… adalah orang-orang seperti saya."],["Dewi Kilisuci","Dan yang bisa mengembalikannya juga orang seperti kamu. Pedang tak bisa melawan lupa. Hanya cerita yang bisa."],["Dewi Kilisuci","Kau akan bertemu seseorang yang mengatakan membiarkan kisah mati adalah belas kasihan. Dengarkan dia baik-baik. Ia tidak sepenuhnya salah."]],"andhap":[["Kirana","Aku menurunkan pelita mengikuti pahatan, bukan memaksanya mengikuti arahku. Cerukan terakhir akhirnya menyala."],["Dewi Kilisuci","Serat Andhap kini bersamamu. Ketuk pelita untuk mengibaskan kabut kecil. Cepat—lorong goa mulai dilupakan!"]],"introGerbang":[["Penjaga","Gerbang ini mengenali nama lama kerajaan. Empat petunjuk tersebar di halaman, menara, gudang, dan batu yang hampir hilang."],["Kirana","Aku harus melihat apa yang tertutup lumut, bayangan, kunci, dan kabut."]],"samarGate":[["Ki Samar","Delapan ratus tahun aku mencatat nama-nama yang berhenti disebut. Sekarang aku hanya merapikan."],["Kirana","Saya membawa kembali sesuatu yang dilupakan."],["Ki Samar","Dilupakan, atau dilepaskan? Bukankah lebih kejam memaksa sebuah kisah hidup di tempat yang tak menginginkannya?"],["Narasi","Ki Samar menghilang. Selama beberapa saat, hanya bunyi langkah Kirana yang tersisa."]],"introKedaton":[["Kirana","Lantainya hilang ketika pelitaku berpaling. Ada langkah lain… tetapi tidak ada pemiliknya."],["Kirana","Bilik buntu mungkin bisa menahan langkah itu. Dan bayangan di pendapa meniru gerakanku terlambat satu detik."]],"galuh":[["Bayang Galuh","Aku hanya iri karena tak ada yang menceritakan versiku."],["Kirana","Aku mendengarmu. Kisah ini ternyata menyisakan lebih dari satu orang di dalam gelap."]],"pusaka":[["Narasi","Puluhan gulungan di lemari pusaka kosong. Satu-satunya nama yang masih tertulis adalah Candra Kirana."],["Kirana","Kirana… seperti namaku."],["Narasi","Huruf itu memudar di bawah jarinya. Kirana menarik tangan, lalu berlari."]],"introBangsal":[["Ki Samar","Jika ingatanmu memang kuat, nyalakan apa yang masih bisa kau jangkau."],["Kirana","Lima pilar. Cahaya dari satu pilar mungkin membuka jalan ke pilar berikutnya."]],"samarEnd":[["Ki Samar","Kau belum menjawab pertanyaanku yang sesungguhnya. Kenapa kisah ini layak diselamatkan, dan kisahku tidak?"],["Kirana","Siapa bilang tidak? Manuskrip ini belum selesai. Tulis namamu."],["Ki Samar","…Apa?"],["Kirana","Kamu bilang kamu menulis dan tidak pernah dibaca. Sekarang ada yang membaca. Saya."],["Ki Samar","Delapan ratus tahun… dan yang kubutuhkan hanya satu orang yang bertanya siapa namaku."]],"introPutri":[["Kirana","Ruangan ini hampir kosong. Tetapi ada seseorang yang masih menunggu di bawah cahaya bulan."],["Candra Kirana","Kepingan-kepingan itu… bisakah kau mengembalikan urutan kisahnya?"]],"putriEnd":[["Candra Kirana","Siapa namamu, gadis muda?"],["Kirana","Kirana, Tuan Putri. Sama seperti nama Tuan Putri."],["Candra Kirana","Tentu saja. Bagaimana kau menyatukan semuanya?"],["Kirana","Satu per satu. Dari kebaikan seorang mbok, kesabaran seorang abdi, sampai orang yang paling ingin semua ini dilupakan."],["Candra Kirana","Maka kau tidak hanya mengumpulkan kertas. Kau menjalaninya. Kembalilah. Ceritakan dengan caramu, dengan bahasamu, di zamanmu."]],"introEpilog":[["Kirana","Hujannya berhenti. Buku itu masih tergeletak di meja, seolah aku baru saja meninggalkannya."],["Kirana","Aku ingin melihat halaman terakhirnya sekali lagi."]],"lastbook":[["Kirana","Semua huruf kembali. Dan di halaman terakhir ada nama yang tidak tertulis sebelumnya: Ki Samar."],["Narasi","Sebuah ilustrasi menunjukkan Mbok Rondo Dadapan menemukan keong emas. Kirana mengenali wajah penjual yang memberinya sarapan."],["Kirana","Mbok tetap tinggal dalam ingatan yang paling keras bertahan. Sekarang giliranku meneruskan ceritanya."]],"golden":[["Narasi","Seorang anak masuk ke perpustakaan. Ia mengambil buku Keong Mas dari meja Kirana."],["Anak","Kak, halaman ini dulu kosong. Siapa Ki Samar?"],["Kirana","Duduklah. Ada sebuah kisah yang ingin kuceritakan."]],"flashbacks":{"Asih":"Mbok Rondo membawa keong yang ditemukannya pulang, tanpa meminta apa pun sebagai balasan.","Sabar":"Di dalam cangkang keemasan, Candra Kirana menunggu tangan yang mau menolongnya.","Jujur":"Tuduhan yang keliru tidak membuat sang putri melepaskan kebenaran yang ia pegang.","Wani":"Putri melangkah meninggalkan gerbang istana, menghadapi jalan yang belum dikenalnya.","Andhap":"Di rumah kecil Mbok Rondo, ia menyiapkan makanan dan membantu pekerjaan tanpa menuntut penghormatan.","Setya":"Sebelum perpisahan datang, sebuah janji di kedaton tetap ia jaga.","Wicaksana":"Pertemuan kembali membuka halaman baru. Cerita dapat bertahan ketika seseorang bersedia meneruskannya."}},"history":[{"id":1,"title":"Manuskrip yang diingat dunia","text":"Manuskrip cerita Panji tercatat dalam Memory of the World UNESCO pada 2017.","source":"https://www.unesco.org/en/memory-world/panji-tales-manuscripts","label":"UNESCO"},{"id":2,"title":"Panji dan Candra Kirana","text":"Dalam cerita Panji, sang pangeran mencari Candra Kirana sampai keduanya bertemu kembali.","source":"https://www.unesco.org/en/memory-world/panji-tales-manuscripts","label":"UNESCO"},{"id":3,"title":"Nama dan penyamaran","text":"Petualangan Panji menggunakan beragam nama dan penyamaran. Variasi merupakan bagian dari tradisi ceritanya.","source":"https://www.unesco.org/en/memory-world/panji-tales-manuscripts","label":"UNESCO"},{"id":4,"title":"Kisah yang menyeberang laut","text":"UNESCO mencatat pedagang laut berperan dalam penyebaran cerita Panji ketika kisah ini populer pada masa Majapahit.","source":"https://www.unesco.org/en/memory-world/panji-tales-manuscripts","label":"UNESCO"},{"id":5,"title":"Warisan bersama","text":"Pendaftaran manuskrip Panji diajukan bersama oleh Kamboja, Indonesia, Malaysia, Belanda, dan Britania Raya.","source":"https://www.unesco.org/en/memory-world/panji-tales-manuscripts","label":"UNESCO"},{"id":6,"title":"Klotok di Kediri","text":"Gunung Klotok berada di Kelurahan Pojok, Kecamatan Mojoroto, Kota Kediri, dekat kaki Gunung Wilis.","source":"https://dpm.kedirikota.go.id/blog/11/gunung-klotok","label":"DPMPTSP Kota Kediri"},{"id":7,"title":"Tiga goa","text":"Pemerintah Kota Kediri mencatat Goa Selomangleng, Selobale, dan Padedean di kawasan Gunung Klotok.","source":"https://dpm.kedirikota.go.id/blog/11/gunung-klotok","label":"DPMPTSP Kota Kediri"},{"id":8,"title":"Dua puncak","text":"Dua puncak Klotok yang disebut pemerintah kota ialah Klop di tengah dan Watu Bengkah di selatan.","source":"https://dpm.kedirikota.go.id/blog/11/gunung-klotok","label":"DPMPTSP Kota Kediri"},{"id":9,"title":"Museum di kaki bukit","text":"Museum Airlangga termasuk tempat yang berada di sekitar kawasan Gunung Klotok.","source":"https://dpm.kedirikota.go.id/blog/11/gunung-klotok","label":"DPMPTSP Kota Kediri"},{"id":10,"title":"Lebih luas dari Jawa","text":"Tradisi Panji menyebar ke Bali, dunia Melayu, Thailand, Myanmar, dan Kamboja.","source":"https://www.unesco.org/en/memory-world/panji-tales-manuscripts","label":"UNESCO"},{"id":11,"title":"Sastra Jawa bertumbuh","text":"UNESCO melihat cerita Panji sebagai bagian penting berkembangnya sastra Jawa di luar bayang-bayang epos India.","source":"https://www.unesco.org/en/memory-world/panji-tales-manuscripts","label":"UNESCO"},{"id":12,"title":"Cerita dan waktu","text":"UNESCO menyebut cerita Panji dari abad ke-13. Latar Kadiri abad ke-11 dan Kutukan Lupa dalam game adalah adaptasi fiksi, bukan kronologi sejarah.","source":"https://www.unesco.org/en/memory-world/panji-tales-manuscripts","label":"UNESCO · catatan adaptasi"}],"site":{"ukmUrl":"","eventDate":"","eventName":"UKM Pendidikan & Penalaran"}});

